changeSet.sql:
CREATE TABLE IF NOT EXISTS conversion_stat_snapshot
(
    conversion_stat_snapshot_id BIGSERIAL PRIMARY KEY,
    snapshot_date               TIMESTAMP NOT NULL,
    success_count               BIGINT,
    error_count                 BIGINT
);
CREATE INDEX IF NOT EXISTS idx_conversion_stat_snapshot_date ON conversion_stat_snapshot(snapshot_date);
COMMENT ON TABLE conversion_stat_snapshot IS 'Снимки статистики успешных/ошибочных конвертаций';
